function prepareRequest(body, from) {
  const name = typeof body?.name === "string" ? body.name.trim() : "";
  const number = typeof body?.number === "string" ? body.number.trim() : "";
  const city = typeof body?.city === "string" ? body.city.trim() : "";
  const phone = /^\+[1-9]\d{6,14}$/;
  if (
    !name ||
    name.length > 120 ||
    !city ||
    city.length > 180 ||
    /[\x00-\x1f\x7f]/.test(name + city) ||
    !phone.test(number)
  ) {
    throw new Error(
      "Send nonempty name and city strings and an international phone number in E.164 format",
    );
  }
  if (typeof from !== "string" || !phone.test(from))
    throw new Error("Configure an SMS-capable Twilio number in E.164 format");
  return { fields: { Name: name, Number: number, City: city }, from };
}

export default ({ body, from, enableWrites }) => {
  if (!enableWrites)
    throw new Error("Configure and verify Webhook Header authentication before enabling writes");
  const prepared = prepareRequest(body, from);
  return { ...prepared, records: [{ fields: prepared.fields }] };
};

