function weatherMessage(weather, query) {
  const { name, sys, main, wind } = weather ?? {};
  const description = weather?.weather?.[0]?.description;
  const country = typeof sys?.country === "string" ? sys.country : "";
  const parts = query.split(",");
  const qualifier = parts.at(-1)?.trim() ?? "";
  if (
    (weather?.cod !== 200 && weather?.cod !== "200") ||
    typeof name !== "string" ||
    !name.trim() ||
    !/^[A-Z]{2}$/.test(country) ||
    (parts.length > 1 && /^[a-z]{2}$/i.test(qualifier) && qualifier.toUpperCase() !== country) ||
    typeof description !== "string" ||
    !description.trim() ||
    !Number.isFinite(main?.temp) ||
    !Number.isFinite(main?.humidity) ||
    main.humidity < 0 ||
    main.humidity > 100 ||
    !Number.isFinite(wind?.speed) ||
    wind.speed < 0
  ) {
    throw new Error("OpenWeather did not confirm complete metric weather for the requested city");
  }
  return (
    "The weather in " +
    name +
    ", " +
    country +
    " is " +
    main.temp +
    " °C with " +
    description +
    ". Humidity is " +
    main.humidity +
    "% and wind speed is " +
    wind.speed +
    " m/s."
  );
}

export default ({ weather, city }) => ({
  body: weatherMessage(weather, city),
});

