function verifySmsReceipt(sms, expected) {
  if (
    typeof sms?.sid !== "string" ||
    !/^SM[0-9a-f]{32}$/i.test(sms.sid) ||
    !["accepted", "queued", "sending", "sent", "delivered"].includes(sms.status) ||
    sms.to !== expected.to ||
    sms.from !== expected.from ||
    sms.body !== expected.body
  ) {
    throw new Error(
      "Twilio did not confirm submission to the requested number. Review Twilio before replaying.",
    );
  }
  return { messageSid: sms.sid, status: sms.status };
}

export default ({ messageSid, status, sentTo, sentFrom, sentBody, to, from, body, recordId }) => {
  const result = verifySmsReceipt(
    { sid: messageSid, status, to: sentTo, from: sentFrom, body: sentBody },
    { to, from, body },
  );
  return { receipt: { recordId, ...result } };
};
